"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["22434"],{42182(e){e.exports=JSON.parse('{"id":"F138","slug":"free-cash-flow-conversion","name":"Free Cash Flow vs. Net Income","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Free cash flow vs. net income","level":"Beginner","aliases":["FCF conversion","cash conversion of earnings","free cash flow yield"],"formula":{"latex":"FCF=CFO-\\\\text{CapEx},\\\\quad \\\\text{Conversion}=\\\\frac{FCF}{NI}","also":[],"text":"Free cash flow = Cash flow from operations - Capital expenditure; Conversion = FCF / Net income; FCF yield = FCF / Market cap"},"symbols":[{"symbol":"CFO","meaning":"Cash flow from operations","unit":"money"},{"symbol":"CapEx","meaning":"Capital expenditure","unit":"money"},{"symbol":"NI","meaning":"Net income","unit":"money"},{"symbol":"Market cap","meaning":"Value of the equity","unit":"money"}],"when_to_use":"Use it to see how much profit is left as cash after spending needed to maintain and grow the business. A company can report profits and still burn cash if capital spending is heavy. Conversion well below 100% for several years is a concern.","worked_example":{"problem":"A company has cash flow from operations of 140, capital expenditure of 80 and net income of 90. Its market cap is 900.","inputs":{"cfo":140,"capex":80,"ni":90,"mc":900},"steps":[{"label":"FCF = CFO - capex","working":"140-80","value":"60.00"},{"label":"Conversion = FCF / net income","working":"60 / 90","value":"66.7%"},{"label":"FCF yield = FCF / market cap","working":"60 / 900","value":"6.67%"}],"answer":"Free cash flow is 60.00. That is 66.7% of net income, and a yield of 6.67% on the market cap."},"calculator":{"available":true,"inputs":[{"id":"cfo","label":"Cash flow from operations","unit":"money","type":"number","default":140,"hint":""},{"id":"capex","label":"Capital expenditure","unit":"money","type":"number","default":80,"hint":""},{"id":"ni","label":"Net income","unit":"money","type":"number","default":90,"hint":""},{"id":"mc","label":"Market capitalization","unit":"money","type":"number","default":900,"hint":""}],"checks":[{"expr":"ni!=0 and mc>0","message":"Net income cannot be zero and market cap must be above zero."}],"steps":[{"id":"fcf","label":"FCF = CFO - capex","expr":"cfo-capex","format":"money"},{"id":"conv","label":"Conversion = FCF / net income","expr":"fcf/ni","format":"pct1"},{"id":"fy","label":"FCF yield = FCF / market cap","expr":"fcf/mc","format":"pct2"}],"results":["fcf","conv","fy"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"fcf":60,"conv":0.6666666666666666,"fy":0.06666666666666667}},"finder":{"finds":"Cash left after investment compared with reported profit","needs":"Operating cash flow, capex, net income, market cap"},"related":[{"slug":"fcff","name":"Free Cash Flow to the Firm (FCFF)"},{"slug":"fcfe","name":"Free Cash Flow to Equity (FCFE)"},{"slug":"accrual-ratio","name":"Accrual Ratio (Earnings Quality)"}],"related_ids":["F207","F208","F137"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>F</mi><mi>C</mi><mi>F</mi><mo>=</mo><mi>C</mi><mi>F</mi><mi>O</mi><mo>\u2212</mo><mtext>CapEx</mtext><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Conversion</mtext><mo>=</mo><mfrac><mrow><mi>F</mi><mi>C</mi><mi>F</mi></mrow><mrow><mi>N</mi><mi>I</mi></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">FCF=CFO-\\\\text{CapEx},\\\\quad \\\\text{Conversion}=\\\\frac{FCF}{NI}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"fcff","name":"Free Cash Flow to the Firm (FCFF)"},"next":{"slug":"fundamental-law-active","name":"Fundamental Law of Active Management"},"lesson":null,"total":522}')}}]);